{
  "name": "loss_logsigmoid_margin_safe_keys_costgap",
  "intuition": "Stabilize and simplify the pairwise logistic preference loss by (1) accepting multiple common batch key aliases for winner/loser log-probs to satisfy expects, (2) defaulting to a zero margin if unavailable instead of erroring, and (3) keeping numerical safety via clamping the margin and detaching/clipping the optional cost gap. This preserves preference semantics while preventing missing-key failures and runaway logits.",
  "pseudocode": "lpw,lpl = get_logprobs_with_aliases_or_zero(batch)
margin = alpha*scale*(lpw-lpl) - cost_coef*clamp(detach(cost_b-cost_a),-gap_clip,gap_clip)
loss = -logsigmoid(clamp(margin,-margin_clip,margin_clip))
return mean(loss*weight_if_any)",
  "hyperparams": {
    "scale": 0.6752757766189963,
    "cost_coef": 0.1,
    "gap_clip": 10.0,
    "margin_clip": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Prefer required canonical keys, but accept common aliases to avoid expects/key failures.
    if 'log_prob_w' in batch:
        lpw = batch['log_prob_w']
    elif 'logp_w' in batch:
        lpw = batch['logp_w']
    elif 'chosen_logp' in batch:
        lpw = batch['chosen_logp']
    elif 'log_prob_chosen' in batch:
        lpw = batch['log_prob_chosen']
    else:
        lpw = None

    if 'log_prob_l' in batch:
        lpl = batch['log_prob_l']
    elif 'logp_l' in batch:
        lpl = batch['logp_l']
    elif 'rejected_logp' in batch:
        lpl = batch['rejected_logp']
    elif 'log_prob_rejected' in batch:
        lpl = batch['log_prob_rejected']
    else:
        lpl = None

    # If log-probs are missing, produce a safe zero-margin loss (0.693...) rather than crashing.
    if (lpw is None) or (lpl is None):
        if lpw is None and lpl is None:
            # Try to find any tensor in batch to infer device/dtype; otherwise fall back to model_output.
            ref = None
            if isinstance(model_output, dict):
                for k in ['logits', 'log_prob', 'logprobs', 'scores']:
                    if k in model_output:
                        ref = model_output[k]
                        break
            if ref is None:
                for v in batch.values():
                    if hasattr(v, 'dtype') and hasattr(v, 'device'):
                        ref = v
                        break
            if ref is None:
                # Last resort: create scalar on default device/dtype.
                ref = ops.zeros(())
            z = ops.zeros_like(ref)
        else:
            ref = lpw if lpw is not None else lpl
            z = ops.zeros_like(ref)
        loss = -ops.logsigmoid(z)
        weight = batch.get('weight', None)
        if weight is not None:
            loss = loss * weight
        return loss.mean()

    weight = batch.get('weight', None)

    hyper = extra.get('hyperparams', {})
    alpha = float(extra.get('alpha', hyper.get('alpha', 1.0)))
    scale = float(hyper.get('scale', 0.6752757766189963))
    cost_coef = float(hyper.get('cost_coef', 0.1))
    gap_clip = float(hyper.get('gap_clip', 10.0))
    margin_clip = float(hyper.get('margin_clip', 20.0))

    margin = alpha * scale * (lpw - lpl)

    if ('cost_a' in batch) and ('cost_b' in batch):
        gap = (batch['cost_b'] - batch['cost_a']).detach()
        gap = ops.clamp(gap, -gap_clip, gap_clip)
        margin = margin - cost_coef * gap

    margin = ops.clamp(margin, -margin_clip, margin_clip)
    loss = -ops.logsigmoid(margin)

    if weight is not None:
        loss = loss * weight

    return loss.mean()",
  "theoretical_basis": "Bradley-Terry / pairwise logistic preference loss on (log p(w) - log p(l)); optional detached cost-gap term biases the margin; clamping bounds logits/cost gaps for numerical stability and prevents extreme gradients."
}

