{
  "name": "e2_consensus_logsigmoid_clamped_margin",
  "intuition": "All parents share a stable core: a pairwise preference objective using a scaled log-probability margin (log_prob_w - log_prob_l) passed through a clamp for numerical stability and optimized via -logsigmoid. A robust consensus choice is to keep this exact backbone while adding a small, safe margin/temperature normalization: center the score by a constant margin and normalize by (1+|scale|) to reduce sensitivity to the exact scale picked across parents (which varies widely). This preserves the monotonic preference signal, keeps gradients well-behaved via clamping, and remains fully vectorized and compatible with optional nonnegative weights.",
  "pseudocode": "s = alpha * scale * (lpw - lpl)\nscore = (s - margin) / (1 + abs(scale))\nloss = -logsigmoid(clamp(score, -20, 20))\nreturn mean(loss * weight?)",
  "hyperparams": {
    "scale": 1.3,
    "margin": 0.0,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "eps": 1e-6
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "abs"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 1.3))\n    margin = float(hp.get('margin', 0.0))\n    clamp_min = float(hp.get('clamp_min', -20.0))\n    clamp_max = float(hp.get('clamp_max', 20.0))\n    eps = float(hp.get('eps', 1e-6))\n\n    s = alpha * scale * (lpw - lpl)\n    # Normalize by a scale-dependent factor to reduce sensitivity to scale choice.\n    denom = 1.0 + ops.abs(ops.tensor(scale))\n    score = (s - margin) / (denom + eps)\n    score = ops.clamp(score, clamp_min, clamp_max)\n    loss = -ops.logsigmoid(score)\n\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) preference loss on the log-probability margin, with clamping for numerical stability. Normalizing by a simple scale-dependent factor preserves ordering while dampening extreme logits when scale is large.",
  "implementation_hint": {
    "expects": {
      "batch": [
        "log_prob_w",
        "log_prob_l"
      ],
      "optional_batch": [
        "weight"
      ],
      "extra": [
        "alpha",
        "hyperparams"
      ],
      "mode": "pairwise"
    }
  }
}

