{
  "name": "consensus_logsigmoid_clamped_costmargin",
  "intuition": "All parents share a stable, well-behaved pairwise preference objective: a clamped log-sigmoid on the log-probability difference (lpw-lpl), optionally scaled by an external alpha and a learned scale. Two parents also inject a detached cost gap as a small margin term that shifts the decision boundary without letting auxiliary costs backpropagate. The consensus-safe synthesis keeps the proven core (-logsigmoid(clamp(alpha*scale*(lpw-lpl)+margin))) and includes an optional detached cost-based margin with conservative weighting, plus optional per-example weighting, preserving numerical stability via clamping.",
  "pseudocode": "delta = lpw - lpl\nmargin = -cost_weight * detach(cost_b - cost_a) if costs available else 0\nx = clamp(alpha * scale * delta + margin, -20, 20)\nloss = -logsigmoid(x)\nreturn mean(loss * weight) if weight else mean(loss)",
  "hyperparams": {
    "scale": 1.3,
    "cost_weight": 0.1,
    "clamp_min": -20.0,
    "clamp_max": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 1.3))\n    cost_weight = float(hp.get('cost_weight', 0.1))\n    cmin = float(hp.get('clamp_min', -20.0))\n    cmax = float(hp.get('clamp_max', 20.0))\n\n    delta = lpw - lpl\n\n    # Optional detached cost-based margin if provided in the batch.\n    if ('cost_a' in batch) and ('cost_b' in batch):\n        gap = (batch['cost_b'] - batch['cost_a']).detach()\n        margin = -cost_weight * gap\n    else:\n        margin = 0.0\n\n    x = alpha * scale * delta + margin\n    x = ops.clamp(x, cmin, cmax)\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss = loss * weight\n\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry / DPO-style) objective on log-probability differences with clamping for numerical stability; optional detached auxiliary margin shifts the preference boundary without propagating gradients through costs.",
  "implementation_hint": {
    "expects": {
      "batch": [
        "log_prob_w",
        "log_prob_l"
      ],
      "optional_batch": [
        "weight",
        "cost_a",
        "cost_b"
      ],
      "extra": [
        "alpha",
        "hyperparams"
      ]
    },
    "notes": "Uses only vectorized tensor ops; cost margin is detached to avoid gradients through cost fields; clamping keeps logits in a stable range."
  }
}

